  "tower.outdated.cta": "Opnieuw laden",
  "tower.hazards.title": "Gevaren op de weg die op jou wachten",
  "tower.hazards.lede": "Chauffeurs melden wat er op de weg ligt, en een chauffeur die zegt dat een gevaar weg is, haalt het niet weg. Het opruimen is de enige manier waarop het stopt met waarschuwen, en alleen van hieruit. Een grens die als gesloten is gemeld, wacht hier of iemand het nu betwist of niet, omdat wat het netwerk eraan doet een besluit van medewerkers is.",
  "tower.hazards.caveatLead": "Alles in deze lijst waarschuwt nog elke chauffeur",
  "tower.hazards.caveat": "— op volle sterkte, en blokkeert nog steeds dezelfde ladingen. Een betwisting verandert op zichzelf niets, en dat is bewust: ongelijk hebben over een brug die er niet is kost een omweg, ongelijk hebben over een brug die er nog wel is kost iemand het leven.",
  "tower.hazards.refresh": "Vernieuwen",
  "tower.hazards.updatedAt": "Gelezen om {time}",
  "tower.hazards.count": "{n} wachten",
  "tower.hazards.borderDecide": "Een besluit van een land",
  "tower.hazards.borderPresence": "Zet het uit onder Aanwezigheid",
  "tower.hazards.borderAdmin": "Een grensovergang uitzetten is voor medewerkers met de beheerrol.",
  "tower.hazards.loading": "De wachtrij lezen…",
  "tower.hazards.emptyTitle": "Niets wordt betwist",
  "tower.hazards.emptyBody": "Geen chauffeur zegt op dit moment dat een gemeld gevaar weg is, en geen grens is als gesloten gemeld. Dat is niet hetzelfde als dat de kaart actueel is — het betekent alleen dat niemand het tegendeel heeft gezegd.",
  "tower.hazards.failedTitle": "Kon de wachtrij niet lezen",
