  "tower.hazards.reportedAt": "Gemeld {date}",
  "tower.hazards.noteLabel": "Opmerkingen van chauffeurs",
  "tower.hazards.accountsCount": "accounts in het dossier: {n}",
  "tower.hazards.sideThere": "Zeg dat het er is ({n})",
  "tower.hazards.sideGone": "Zeg dat het weg is ({n})",
  "tower.hazards.saidNothing": "Ze voegden geen woorden toe.",
  "tower.hazards.photoTitle": "Wat ze fotografeerden",
  "tower.hazards.photoNone": "Geen foto bij deze. Dat is geen reden om het af te doen — een chauffeur die niet veilig kon stoppen meldde toch wat hij zag.",
  "tower.hazards.noAccounts": "Dit gevaar is gemeld voordat accounts werden bijgehouden, dus alles wat er is om op af te gaan is de opmerking en de aantallen hierboven. Bel de vervoerder voordat je het opruimt.",
  "tower.hazards.openMap": "Openen op een kaart",
  "tower.hazards.longWait": "Wacht al een tijdje",
  "tower.hazards.clear": "Dit opruimen",
  "tower.hazards.clearTitle": "Haal dit van de kaart van elke chauffeur",
  "tower.hazards.clearBody": "Het stopt onmiddellijk, overal, met waarschuwen. Het dossier wordt bewaard met je naam en je reden, zodat het besluit kan worden beoordeeld — en een chauffeur die het opnieuw tegenkomt kan het opnieuw melden.",
  "tower.hazards.reason": "Waarom wordt het opgeruimd?",
  "tower.hazards.reasonPlaceholder": "bijv. De gemeente bevestigde dat de brug op 4 september is herbouwd tot 6,0 m",
  "tower.hazards.reasonHint": "Voor altijd bewaard, en gelezen door wie later vraagt waarom dit gevaar verdween.",
  "tower.hazards.reasonNeeded": "Een reden is verplicht.",
  "tower.hazards.confirm": "Opruimen",
  "tower.hazards.cancel": "Houden",
