  "tower.hazards.clearFailed": "Dat kon niet worden opgeruimd",
  "tower.papers.title": "Papieren: koeriers en voertuigen zonder vervoerder",
  "tower.papers.lede": "Een vervoerder legt de verlengingen van zijn eigen voertuigen en chauffeurs vast in de Fleet-app. Een koerier die zonder vervoerder rijdt, en een voertuig dat geen vervoerder bezit, hebben geen kantoor om dat te doen — een rijbewijs dat verloopt zet ze uit de roulatie zonder dat iemand het hoort. Leg hier vast wat je hebt gezien; de nieuwe datum is de hele verlenging.",
  "tower.papers.refused": "Niet vastgelegd",
  "tower.papers.failedTitle": "Kon de papieren niet lezen",
  "tower.papers.loading": "Lezen…",
  "tower.anchors.title": "Het spoor, verankerd buiten onze database",
  "tower.anchors.lede": "Elke ophaling, aflevering, zegel, scan en schademelding krijgt een vingerafdruk in één keten. Eén keer per dag gaat de nieuwste schakel naar het adres van een auditor, waar wij hem niet kunnen wijzigen. Als iets tot aan die schakel later wordt gewijzigd, geeft de keten niet meer dezelfde schakel, en de kopie van de auditor laat dat zien.",
  "tower.anchors.notMatching": "{n, plural, one {# dag komt niet meer overeen} other {# dagen komen niet meer overeen}}",
  "tower.anchors.notDelivered": "Er is nog geen mailprovider aangesloten: elke dag wordt hier bewaard, en de e-mail wacht in de uitbak totdat er een is.",
  "tower.anchors.auditor": "Het adres van de auditor",
