  "tower.shopLicences.title": "Handelsvergunningen van winkels",
  "tower.shopLicences.lede": "Medewerkers noteren de datum waartot de vergunning van een winkel loopt als hij wordt goedgekeurd, en opnieuw bij elke verlenging. De winkel krijgt dertig dagen van tevoren bericht; veertien dagen nadat hij is verlopen kan er daar geen nieuw pakket meer beginnen totdat de verlengde is vastgelegd. Geboekte pakketten en het schap gaan door.",
