  "tower.observations.title": "Waar aan de grens om werd gevraagd",
  "tower.observations.lede": "Verhalen uit eerste hand van chauffeurs en expediteurs aan een loket: welk papier, waar, op welke dag. De regels hierboven zijn aan ons om bij te houden; dit is iemands middag, en zo worden ze getoond.",
  "tower.observations.basis": "Niet wat een grens eist. Een eis die is vervallen laat zich hier zien doordat sindsdien niemand er meer om is gevraagd — niets wordt ooit met de hand als verouderd gemarkeerd.",
