  "tower.observations.remove": "De foto terugnemen",
  "tower.observations.removeKeeps": "De waarneming blijft — ze was uit eerste hand en is het nog steeds. Alleen de foto gaat weg, en je reden wordt ernaast bewaard.",
  "tower.observations.why": "Waarom",
  "tower.observations.removed": "Verwijderd. De waarneming staat er nog, nu zonder foto.",
  "tower.papers.transitTitle": "Wie ongeklaarde goederen mag vervoeren",
  "tower.papers.transitLede": "Een container die in het binnenland wordt ingeklaard reist onder douanetoezicht van de kade, en alleen een vervoerder met een transitvergunning in dat land krijgt de lading aangeboden. Een vervoerder bewaart zijn eigen rijbewijzen in de Fleet-app; deze heeft geen ander kantoor dan het onze, en als hij verloopt, krijgt de vervoerder gewoon geen werk onder douanetoezicht meer aangeboden.",
  "tower.papers.transitBasis": "Vastgelegd zoals de vervoerder het opgeeft, op naam van wie het typte. We controleren dat er een bestaat en dat hij geldig is; we verifiëren hem niet bij de autoriteit die hem heeft uitgegeven.",
  "tower.papers.transitNone": "Niemand is vastgelegd als iemand die ongeklaarde goederen kan vervoeren.",
