  "tower.market.title": "Wat de markt doet",
  "tower.market.lede": "Waar verladers om vroegen, tegenover wat de vervoerders echt aannamen — dag voor dag, hoe lang ladingen wachten, waartegen onderhandelde prijzen werden gesloten, en welke lanes stil werden.",
  "tower.market.caveatT": "Niemand meldt dit.",
  "tower.market.caveat": "Elk cijfer hier is afgeleid van tijdstempels die een lading al heeft. Een vervoerder die capaciteit terugtrekt dient geen bericht in — hij stopt gewoon met aannemen — dus deze lijnen bewegen binnen een dag vanzelf, en dat is de enige reden dat ze te vertrouwen zijn in een markt waar mensen het druk hebben en formulieren oningevuld blijven.",
