  "tower.movers.why": "Waarom",
  "tower.movers.handBacksTitle": "Waarom ladingen werden teruggegeven",
  "tower.movers.handBacksWhy": "Niet op hun openbare pagina, en dat is bewust. Een chauffeur wiens rust aan de beurt was, heeft het juiste gedaan door een lading terug te geven — de reden publiceren zou het eerlijke gebruik van een regel die wij schreven bestraffen, en het antwoord daarop zijn chauffeurs die moe blijven rijden. Het AANTAL is openbaar; de reden is voor wie een klacht behandelt.",
