  "tower.pilot.how.loss": "Kwijt of beschadigd: pakketten die die week als kwijt zijn opgegeven en niet zijn gevonden toen de week werd vastgezet, en problemen die die week bij pakketten zijn gemeld, per pakket dat die week is aangenomen. Doel onder {target}; boven {warn} moet er een naam bij.",
  "tower.pilot.how.takeIn": "Aanneemtijd: het midden van de tijden die de app van de winkels mat, vanaf de eerste aanraking bij het aannemen tot het pakket is aangenomen. Langer dan 15 minuten was onderbroken, niet traag, en wordt niet meegeteld. Doel onder {target} s; boven {warn} s moet er een naam bij.",
  "tower.pilot.how.retention": "Oorspronkelijke winkels die werken: van de winkels die in de eerste week van de pilot een balie bemanden, het aandeel dat er deze week een bemande. Beoordeeld vanaf week {week}, tegen {target}.",
  "tower.pilot.how.frozen": "Overdrachten en aanneemtijden worden geteld vanaf 18 oktober 2026, toen ze werden bijgehouden; eerdere weken laten er geen getal voor zien.",
