  "tower.reports.title": "Schadeclaimrapporten",
  "tower.reports.lede": "Elk gemeld probleem, nieuwste eerst. Medewerkers beslissen hier niets: het rapport is gemaakt op het moment dat het probleem werd gemeld, uit de vastlegging zoals die toen was, en voor wie het is, geeft het aan de eigen verzekeraar.",
  "tower.reports.caveatT": "Niets hier verwijdert iets.",
  "tower.reports.caveat": "Gesprekken worden nooit bewerkt of verwijderd, zodat ze getoond kunnen worden als twee mensen het oneens zijn. Handel naar de persoon, niet naar het bericht: een patroon bij meerdere melders is wat telt.",
