  "tower.rates.title": "Wat elk zusterbedrijf rekent",
  "tower.rates.lede": "Elk zusterbedrijf prijst voor zichzelf, per soort werk. De drie lagen worden opgeteld, nooit over elkaar heen berekend, en elke laag kan worden ingesteld voor één lane of voor alles.",
  "tower.rates.caveatLead": "De verdeling is alleen van ons.",
  "tower.rates.caveat": "Een koper ziet een prijs; een verkoper ziet één regel platformvergoeding; niemand buiten dit scherm ziet hem in drieën verdeeld. Hij is gescheiden zodat iemand kan beantwoorden of we verdienen omdat de markt goed is of omdat we een risico dragen waar niemand voor betaalt — een vraag die met één samengenomen percentage niet te stellen is.",
  "tower.rates.pickSister": "Welk bedrijf",
  "tower.pick.search": "Bedrijven zoeken — naam, land of valuta",
  "tower.pick.total": "bedrijven: {n}",
  "tower.pick.matching": "{shown} van {all} getoond",
  "tower.pick.none": "Geen bedrijf past bij “{q}”.",
  "tower.rates.group": "Het moederbedrijf",
  "tower.rates.groupLead": "{name} rekent niets.",
  "tower.rates.groupBody": "Het is nergens de merchant of record en nooit partij bij een klanttransactie, dus het heeft geen tarieven om in te stellen. Zijn licentievergoeding verdient het in plaats daarvan van de zusterbedrijven. Getoond in plaats van verborgen, zodat wie naar zijn tarieven zoekt, een antwoord krijgt.",
  "tower.rates.whatItCharges": "Wat {name} rekent",
  "tower.rates.registeredAs": "Int belasting als {registration}",
  "tower.rates.notRegistered": "Niet geregistreerd om belasting te innen",
  "tower.rates.loading": "De tarieven lezen…",
