  "tower.companies.lede": "Elk is een apart bedrijf met een eigen valuta, een eigen belastingregistratie en een eigen boekhouding. Dit is de enige plek waar ze naast elkaar gelezen kunnen worden.",
  "tower.companies.caveatLead": "Hier wordt niets opgeteld.",
  "tower.companies.caveat": "Deze bedrijven rekenen af in verschillende valuta’s, en een totaal over alle zou een getal zijn dat op een manier fout is die niemand kan zien. Elke kolom blijft in zijn eigen geld.",
  "tower.companies.loading": "De bedrijven lezen…",
  "tower.companies.groupCharges": "Het moederbedrijf rekent niets: het is nergens de merchant of record en nooit partij bij een klanttransactie. Zijn licentievergoeding verdient het van de zusterbedrijven.",
  "tower.companies.noPricing": "Kon niet lezen wat dit bedrijf rekent.",
  "tower.companies.noBooks": "Kon de boeken van dit bedrijf niet lezen. Getoond als ontbrekend in plaats van als nul — een saldo van nul en een onbeantwoorde vraag zien er hetzelfde uit en betekenen het tegenovergestelde.",
  "tower.companies.groupBooks": "Het rekent in geen eigen valuta af, dus er is niets om tegen wat het verschuldigd is te houden — dekking is een vraag die alleen aan een handelsbedrijf gesteld kan worden. De boeken moeten nog steeds sluiten, en dat doen ze.",
