  "tower.company.ledeOwn": "Het dossier van je bedrijf is aan jou om bij te houden. De wettelijke gegevens, adressen, eigenaren, belastingnummers en wat het land vereist: wijzig en sla op. Een vergunning, een verzekeringspolis, een bankrekening of wie mag tekenen wijzigt telkens één per keer, samen met het papier erachter, en telt vanaf dat moment. Je mede-beheerders, en het bedrijf boven het jouwe, krijgen een e-mail bij elke zo’n wijziging.",
  "tower.company.ledeDraft": "Je bedrijf is nog niet ingeschakeld. Tot het zover is, voeren medewerkers van SeeBuyGet het dossier in en verifieert een tweede persoon elk papier. Leg je papieren vast onder Papieren. Zodra het is ingeschakeld, is het dossier aan jou om bij te houden.",
  "tower.company.ledeTheirs": "Dit bedrijf is ingeschakeld en houdt zijn eigen dossier bij: zijn beheerders wijzigen het, elke vergunning, polis, bankrekening en tekenbevoegde samen met het papier erachter. Jij leest het.",
  "tower.company.lede": "Alles wat een bedrijf echt maakt — zijn rechtsvorm, registratie, de mensen die mogen tekenen, zijn eigenaren, belastingnummers, bank, vergunningen, verzekering en de papieren erachter. Hier ingevoerd, vanaf de kant van het netwerk, voordat zijn land wordt ingeschakeld.",
  "tower.company.choose": "Bedrijf",
  "tower.company.loading": "Het dossier lezen…",
  "tower.company.groupNoRecord": "De groep houdt hier geen operationeel dossier bij — ze is nergens partij bij.",
