  "tower.company.fold.switchedOff": "Kan niet langer {list}",
  "tower.company.runningOut.own": "Verleng elk bij wie het heeft afgegeven, druk dan hieronder onder Vergunningen of Verzekering op “Wijzigen, met zijn papier”: voer de nieuwe datum in en voeg het verlengde papier toe. Het telt vanaf dat moment. Je beheerders krijgen 60, 30, 14, 7 en 1 dag van tevoren een e-mail, en op de dag dat een papier is verlopen.",
  "tower.company.runningOut.ownDraft": "Verleng elk bij wie het heeft afgegeven en leg het verlengde papier dan hieronder vast onder Papieren. Tot je bedrijf is ingeschakeld, voeren medewerkers van SeeBuyGet de nieuwe datum in.",
  "tower.company.runningOut.staff": "Het bedrijf verlengt zijn eigen papieren: een van zijn beheerders voert de nieuwe datum in met het verlengde papier erbij, en het telt meteen. Ze krijgen 60, 30, 14, 7 en 1 dag van tevoren een e-mail, en op de dag dat een papier is verlopen.",
  "tower.company.runningOut.staffDraft": "Nog niet ingeschakeld, dus zijn dossier is aan jou om in te voeren: zodra het verlengde papier onder Papieren is vastgelegd en geverifieerd, voer je de nieuwe datum in onder Vergunningen of Verzekering hieronder.",
  "tower.company.declare.hint": "Elk hiervan wijzigt één per keer, samen met het papier erachter. Het telt vanaf dat moment, en je mede-beheerders en het bedrijf boven het jouwe worden ingelicht.",
