  "tower.paperReport.title": "Gemelde papieren",
  "tower.paperReport.lede": "Iemand die is ingelogd en aan een bedrijf is gekoppeld, heeft gezegd dat een van zijn papieren niet klopt, en heeft toegevoegd wat het laat zien. Het papier blijft meetellen terwijl je kijkt. Een van jullie mag een melding afwijzen, met de reden. Het papier schrappen vraagt twee van jullie — een stelt voor, een tweede keurt goed — en niet voordat het bedrijf heeft geantwoord of zijn zeven dagen om zijn.",
