  "tower.custodyCaps.none": "geen limiet",
  "tower.custodyCaps.hint": "Hoeveel pakketten een nieuwe winkel tegelijk in bewaring heeft, en een nieuwe koerier zonder vervoerder tegelijk vervoert. Elke limiet groeit met één bij elk doorgegeven pakket en wordt opgeheven na het aantal dat je instelt. Laat beide vakken leeg voor geen limiet. De chauffeurs van een vervoerder hebben hier geen limiet: hun vervoerder staat voor hen in. Begin laag — een koerier op 3, opgeheven na 50 — en verhoog het naarmate je land leert wie er bezorgt.",
