  "tower.carrierPapers.currentNone": "Niets afgedwongen — de standaard",
  "tower.carrierPapers.hint": "De transportvergunning van een vervoerder en zijn dekking voor goederen onderweg worden vastgelegd en getoond op het scherm Papieren, wat je hier ook kiest. Dit bepaalt alleen wat een verlopen papier DOET: afgedwongen gaan de ritten van de vervoerder van de vrachtenbeurs en kan hem geen nieuw werk worden verkocht totdat het papier is verlengd; niet afgedwongen blijft het een waarschuwing waar iemand iets mee moet doen. Ritten die al bezig zijn, worden altijd afgemaakt. De meeste vervoerders zijn aangemeld zonder deze data — leg ze vast voordat je afdwingt, anders verandert er niets.",
