  "tower.claims.freightNoAward": "Niemand is voor deze lading via het netwerk gefactureerd, dus er is niets om uit toe te kennen. Wijs hem toe met een reden die zegt dat het geld tussen afzender en vervoerder ligt, of wijs hem af.",
  "tower.claims.freightDecideBodyNoBooks": "Het netwerk heeft niets gefactureerd voor deze lading, dus hier kan geen geld worden toegekend. Toewijzen legt vast dat de afzender gelijk had en dat het vervoer aan hen en de vervoerder is om te regelen; de afzender krijgt in beide gevallen je reden te zien.",
