  "tower.drivers.title": "Aanmeldingen van chauffeurs",
  "tower.drivers.lede": "Chauffeurs met een zwaar voertuig die op ons wachten — nieuwe koeriers, en chauffeurs zonder vervoerder die vragen om voor zichzelf te rijden. Wat wordt beoordeeld, is of deze persoon wettelijk mag rijden, dus het rijbewijs dat ze stuurden, wordt op de rij getoond in plaats van achter een tik.",
  "tower.drivers.asks": "Zonder vervoerder, vraagt om voor zichzelf te rijden: {vehicle} {plate}, woonachtig in {country}. Goedkeuren maakt hen er een koerier mee; het controleren van de staat van dienst is aan jou om af te vinken.",
