  "tower.docs.title": "Voorwaarden en berichten",
  "tower.docs.lede": "Waar iedereen mee akkoord gaat bij het aanmelden: de gebruiksvoorwaarden, wat er met hun gegevens gebeurt en cookies — de algemene teksten, en wat het recht van een land toevoegt. Een wijziging is een nieuwe versie: een van jullie schrijft haar met een notitie die zegt wat er veranderde, en een ander publiceert haar. Iedereen die het aangaat, wordt in zijn app ingelicht. Elke versie wordt bewaard en kan worden gelezen en vergeleken.",
