  "tower.ids.retakeCta": "Vraag hen de foto’s opnieuw te nemen",
  "tower.ids.weighTitle": "Wat je moet afwegen",
  "tower.ids.note.holderSilent": "De houder heeft in zijn week niets gestuurd. Als de kaart van de aanvrager het nummer draagt, kan het ID naar hem gaan. De registratie van de houder wordt dan vastgehouden, niet verwijderd.",
  "tower.ids.note.claimantDiffers": "De eigen kaart van de aanvrager draagt een ander nummer. Hij typte dat van iemand anders toen hij zich registreerde: het ID blijft waar het is, en hij registreert zich met het nummer op zijn kaart.",
  "tower.ids.note.holderDiffers": "De eigen kaart van de houder draagt een ander nummer: het zijne was verkeerd getypt. Als het ID naar de aanvrager gaat, krijgt het dossier van de houder het nummer dat je hebt gelezen en wordt niemand vastgehouden.",
  "tower.ids.note.bothMatch": "Beide kaarten dragen dit nummer, dus een ervan is niet echt, en een foto kan niet altijd zeggen welke. Vergelijk elk gezicht met zijn kaart, de referentie op elke eerste foto, en wat de houder stuurde toen hij zich registreerde. Als je het niet kunt zeggen, laat het dan bij de houder en zeg dat erbij: wie het niet krijgt, kan met de kaart zelf langskomen.",
  "tower.ids.note.nothingOnRecord": "De houder stuurde bij zijn registratie geen kopie van een ID, dus er is niets eerders om zijn foto’s mee te vergelijken.",
  "tower.ids.sentBack": "Teruggestuurd wegens {why}",
  "tower.ids.wait.opened": "Wacht op de foto’s van de aanvrager. De houder is nog niet op de hoogte gebracht.",
