  "tower.ids.wait.appointment": "Er is een afspraak gemaakt. Wat daar wordt gezien, wordt vanaf die dag vastgelegd.",
  "tower.ids.over": "Hier valt niets meer te beslissen.",
  "tower.ids.proposeLede": "Lees eerst het nummer op elke kaart. Zeg dan van wie het ID is. Er verandert niets totdat een tweede medewerker het goedkeurt.",
  "tower.ids.recordLede": "De dag van de afspraak is aangebroken. Zeg wie er kwam, lees het nummer op elke kaart die je is getoond, en zeg van wie het ID is. Een tweede medewerker keurt het goed, en dat is definitief.",
