  "tower.ids.cannot.claimantCard": "Lees eerst het nummer op de kaart van de aanvrager. Het ID kan alleen naar iemand gaan wiens kaart het draagt.",
  "tower.ids.cannot.holderCard": "De houder heeft geen kaart met dit nummer laten zien, en de kaart van de aanvrager is niet gelezen als een kaart met een ander nummer. Lees eerst de kaarten.",
  "tower.ids.cannot.notCame": "De beslissing kan alleen veranderen voor iemand die met de eigen kaart is gekomen.",
  "tower.ids.means.claimant": "Het ID wordt bewaard voor degene die werd geweigerd, tot die zich registreert. De registratie van de houder wordt vastgehouden: die maakt af waar die mee bezig is en begint niets nieuws tot er een eigen ID van die persoon is vastgelegd.",
  "tower.ids.means.claimantCorrected": "Het ID wordt bewaard voor degene die werd geweigerd, tot die zich registreert. De gegevens van de houder nemen het nummer over dat je op de eigen kaart hebt gelezen, en verder verandert er niets voor die persoon.",
