  "tower.moves.title": "Accountverplaatsingen",
  "tower.moves.lede": "Wie het telefoonnummer kwijt is, de PIN is vergeten en het herstel-e-mailadres niet kan lezen, komt zelf niet meer in het account. Twee van ons kunnen het naar een nieuw nummer verplaatsen: de een controleert wie het vraagt en schrijft op wat is gecontroleerd, de ander keurt goed. Het is ook precies wat iemand zou vragen die achter het account van een ander aan zit — dus controleer eerst, en vergelijk wat het account zegt met wat die persoon vertelt.",
