  "tower.moves.warn.nothingToCheck": "Dit account verstuurt en haalt alleen pakketten op: we hebben er geen ID voor en geen naam buiten de kluis. Er is weinig om iemand mee te vergelijken — vraag wat die persoon onlangs heeft verstuurd of opgehaald, en vanwaar.",
