  "tower.moves.decideTitle": "Beslis",
  "tower.moves.checkLede": "Jij bent de eerste van twee. Controleer wie het vraagt — bekijk het ID als het account er een heeft vastgelegd, vraag wat alleen de eigenaar zou weten — en schrijf op wat je hebt gecontroleerd. Er verplaatst nog niets: een tweede medewerker keurt goed op basis van wat jij schrijft.",
  "tower.moves.checkWhat": "Wat je hebt gecontroleerd, en hoe",
  "tower.moves.checkHint": "Bijvoorbeeld: “Hun nationale ID-kaart gezien op het kantoor in Nairobi; het nummer klopt.” Het wordt bij het verzoek bewaard.",
  "tower.moves.checkCta": "Ik heb gecontroleerd wie het vraagt",
  "tower.moves.approveLede": "{who} heeft gecontroleerd wie het vraagt. Als wat is opgeschreven je tevredenstelt, keur dan goed: het account gaat direct naar het nummer dat eindigt op {ends} en elke telefoon die erop is ingelogd, wordt uitgelogd. De houder krijgt bericht en kan het 24 uur lang ongedaan maken met het oude nummer en de PIN zoals die was.",
