  "tower.gs1.waiting": "{n, plural, =0 {Niets in afwachting} one {Eén in afwachting} other {# in afwachting}}",
  "tower.gs1.lede": "Een bedrijf zegt dat een GS1-bedrijfsprefix die een ander bedrijf gebruikt, van henzelf is. Lees beide licenties: de prefix en het bedrijf waaraan die is toegekend staan op elk. Een van jullie zegt van wie hij is en waarom; een ander keurt goed. Als beslist wordt voor degene die erom vroeg, stoppen de anderen met printen eronder, en hun ladingen houden de codes die ze kregen.",
