  "tower.hubList.lede": "Elke hubplek in dit land: de hubs die er zijn, de plekken waar de kaart zegt dat een hub nodig is, en de plekken die je toevoegt. Vul een rij in als je een hub vindt, zet hem op in gesprek, en stuur de uitnodiging vanuit de rij — de aanmelding als hub met de plek en de code van de rij. Meldt de hub zich daarmee aan, dan wordt de rij vanzelf aangesloten. Een afgewezen rij komt na 90 dagen weer open, of eerder als de cijfers verdubbelen.",
