  "tower.catchments.hint": "{hubs, plural, one {# hub} other {# hubs}} · {unserved, plural, =0 {elke zone bediend} one {# zone zonder hub} other {# zones zonder hub}}",
  "tower.catchments.lede": "Een net van hubs: elke goedgekeurde hub bedient zelf de zone waarin die staat, een hub kan naburige zones toevoegen vanuit de eigen app, en jij voegt een hub aan een zone toe of haalt er een weg — ook de zone waarin die staat. Een pakket gaat naar de hub van zijn zone die het dichtst bij zijn winkel ligt en ruimte heeft op de vloer. Een zone zonder hub wordt gerouteerd zoals eerder, op de gebiedsnaam die de winkels typten; een zone die sindsdien is samengevoegd of gesplitst, houdt de hubs die zijn toegevoegd aan de zone waaruit hij is gemaakt, tot hij een eigen hub heeft.",
