  "tower.prices.title": "Prijzen",
  "tower.prices.lede": "De prijskaart van je land: wat een pakket kost tussen twee van je zones, naar hoe ver ze uit elkaar liggen en wat het weegt, met een bedrag voor de uiteinden van elke groep en je toeslagen. De eigen vergoedingen van de twee winkels, onze vergoeding en de belasting komen erbij, zoals nu. Een kaart wordt door een tweede persoon goedgekeurd en gaat in vanaf een datum die minstens je aankondigingstermijn in de toekomst ligt. Totdat een kaart van kracht is, worden prijzen berekend zoals eerder.",
